const offerSearch=offerField('search','Rechercher une opportunité','search');offerSearch.required=false;offerSearch.maxLength=120;
const offerFind=document.createElement('button');offerFind.type='button';offerFind.textContent='Rechercher les opportunités';offerForm.append(offerFind);
const offerOpportunity=offerField('opportunity_id','Opportunité associée','select');offerOpportunity.append(option('','Sélectionner'));
offerField('title','Intitulé du brouillon','text').maxLength=180;offerField('valid_until','Validité jusqu’au','date');
const offerSave=document.createElement('button');offerSave.textContent='Enregistrer le brouillon SaaS';offerForm.append(offerSave);
const offerNotice=document.createElement('p');offerNotice.id='saas-offer-notice';offerNotice.setAttribute('role','status');
const offerRows=document.createElement('div');offerRows.id='saas-offer-rows';const offerPager=document.createElement('div');offerPager.className='toolbar';const offerPrev=document.createElement('button'),offerNext=document.createElement('button'),offerPageLabel=document.createElement('span');offerPrev.textContent='Précédent';offerNext.textContent='Suivant';offerPager.append(offerPrev,offerPageLabel,offerNext);
offerSection.append(offerHeading,offerIntro,offerForm,offerNotice,offerRows,offerPager);saasSection.after(offerSection);const offerLink=document.createElement('a');offerLink.href='#saas-offers';offerLink.textContent='Offres SaaS';document.querySelector('.workflow-nav').append(offerLink);
let offerPage=1,offerEpoch=0,offerLookupEpoch=0;
const subscriptionSection=document.createElement('section');subscriptionSection.id='saas-subscriptions';subscriptionSection.className=offerSection.className;
const subscriptionHeading=document.createElement('h2');subscriptionHeading.textContent='Abonnements SaaS';
const subscriptionIntro=document.createElement('p');subscriptionIntro.textContent='Registre interne des engagements documentés. Aucun paiement, contrat ou accès logiciel créé automatiquement. La date de fin est exclusive.';
const subscriptionSearch=document.createElement('input');subscriptionSearch.type='search';subscriptionSearch.placeholder='Rechercher client, offre ou référence';subscriptionSearch.setAttribute('aria-label','Rechercher un abonnement SaaS');
const subscriptionNotice=document.createElement('p');subscriptionNotice.setAttribute('role','status');
const subscriptionRows=document.createElement('div');subscriptionRows.id='saas-subscription-rows';
const subscriptionPager=document.createElement('div');subscriptionPager.className='toolbar';const subscriptionPrev=document.createElement('button'),subscriptionNext=document.createElement('button'),subscriptionPageLabel=document.createElement('span');subscriptionPrev.textContent='Précédent';subscriptionNext.textContent='Suivant';subscriptionPager.append(subscriptionPrev,subscriptionPageLabel,subscriptionNext);
const subscriptionMetrics=document.createElement('div');subscriptionMetrics.id='saas-subscription-metrics';const subscriptionFilter=document.createElement('select');subscriptionFilter.setAttribute('aria-label','État des abonnements SaaS');for(const [value,label] of Object.entries({'':'Tous les états',PLANIFIE:'Planifiés',ACTIF:'Actifs',EXPIRE:'Expirés',ECHEANCE_30J:'Échéance sous 30 jours'}))subscriptionFilter.append(option(value,label));
subscriptionSection.append(subscriptionHeading,subscriptionIntro,subscriptionMetrics,subscriptionSearch,subscriptionFilter,subscriptionNotice,subscriptionRows,subscriptionPager);offerSection.after(subscriptionSection);const subscriptionLink=document.createElement('a');subscriptionLink.href='#saas-subscriptions';subscriptionLink.textContent='Abonnements SaaS';document.querySelector('.workflow-nav').append(subscriptionLink);
let subscriptionPage=1,subscriptionEpoch=0,subscriptionTimer;
function renderSubscriptionMetrics(metrics){subscriptionMetrics.replaceChildren();const heading=document.createElement('p');heading.textContent='Situation globale au '+metrics.as_of+' : '+metrics.counts.ACTIF+' actifs · '+metrics.counts.PLANIFIE+' planifiés · '+metrics.counts.EXPIRE+' expirés · '+metrics.counts.ECHEANCE_30J+' échéance(s) sous 30 jours.';subscriptionMetrics.append(heading);for(const group of metrics.groups){const p=document.createElement('p');p.textContent=group.product_name+' · '+group.active+' actif(s) · MRR estimé '+group.mrr+' '+group.currency+' · ARR estimé '+group.arr+' '+group.currency;subscriptionMetrics.append(p)}}
subscriptionFilter.onchange=()=>{clearTimeout(subscriptionTimer);subscriptionPage=1;if(token)loadSubscriptions()};
async function loadSubscriptions(){const current=++subscriptionEpoch,session=token;try{const d=await api('crm/saas-subscriptions?'+new URLSearchParams({page:subscriptionPage,q:subscriptionSearch.value,status:subscriptionFilter.value}));if(!token||token!==session||current!==subscriptionEpoch)return;renderSubscriptionMetrics(d.metrics);subscriptionRows.replaceChildren();for(const item of d.items){const box=document.createElement('details'),heading=document.createElement('summary'),info=document.createElement('p');heading.textContent=item.company+' — '+item.title+' · '+item.status;info.textContent=item.estimate.product_name+' · '+item.starts_on+' → '+item.ends_on+' (exclue) · Référence : '+item.reference+' · MRR estimé : '+item.estimate.mrr+' '+item.estimate.currency+' · ARR estimé : '+item.estimate.arr+' '+item.estimate.currency;const context=document.createElement('p');context.textContent='Identifiant : '+item.id+' · '+(item.predecessor_id?'Renouvellement de '+item.predecessor_id:'Abonnement initial')+' · '+(item.successor_id?'Renouvellement enregistré':item.status==='ACTIF'&&item.days_to_end<=30?'Échéance dans '+item.days_to_end+' jour(s)':'');box.append(heading,info,context);subscriptionBilling(item,box);subscriptionRows.append(box)}if(!d.items.length)subscriptionRows.textContent='Aucun abonnement.';subscriptionPageLabel.textContent='Page '+subscriptionPage+' · '+d.total+' abonnement(s)';subscriptionPrev.disabled=subscriptionPage===1;subscriptionNext.disabled=subscriptionPage*10>=d.total}catch(e){if(token===session&&current===subscriptionEpoch)subscriptionNotice.textContent=e.message}}
function subscriptionBilling(item,box){const button=document.createElement('button'),panel=document.createElement('div');button.type='button';button.textContent='Voir l’échéancier de facturation';panel.hidden=true;box.append(button,panel);let page=1,epoch=0;async function load(){const session=token,current=++epoch;try{const path='crm/saas-subscriptions/'+encodeURIComponent(item.id)+'/billing';const d=await api(path+'?page='+page);if(!token||token!==session||current!==epoch||!box.isConnected)return;panel.replaceChildren();const intro=document.createElement('p');intro.textContent=d.prepared_count+'/'+d.total+' échéances préparées · montants HT indicatifs, aucune facture émise.';panel.append(intro);for(const period of d.items){const row=document.createElement('div'),label=document.createElement('p');label.textContent=period.period_start+' → '+period.period_end+' (exclue) · '+period.total_ht+' '+period.currency+' HT · '+(period.prepared?'Préparée':'À préparer');row.append(label);if(d.can_prepare&&!period.prepared){const save=document.createElement('button');save.type='button';save.textContent='Préparer cette échéance';save.onclick=async()=>{if(!confirm('Enregistrer cette préparation interne, sans émission de facture ?'))return;save.disabled=true;try{await api(path,{method:'POST',body:JSON.stringify({period_start:period.period_start})});if(token===session)await load()}catch(e){if(token===session&&box.isConnected){label.textContent=e.message;save.disabled=false}}};row.append(save)}panel.append(row)}const prev=document.createElement('button'),next=document.createElement('button');prev.textContent='Précédent';next.textContent='Suivant';prev.disabled=page===1;next.disabled=page*10>=d.total;prev.onclick=()=>{page--;load()};next.onclick=()=>{page++;load()};panel.append(prev,next)}catch(e){if(token===session&&current===epoch&&box.isConnected)panel.textContent=e.message}}button.onclick=()=>{panel.hidden=!panel.hidden;if(!panel.hidden)load();else epoch++}}
subscriptionSearch.oninput=()=>{clearTimeout(subscriptionTimer);subscriptionEpoch++;subscriptionPage=1;subscriptionPrev.disabled=subscriptionNext.disabled=true;subscriptionTimer=setTimeout(()=>{if(token)loadSubscriptions()},250)};
subscriptionPrev.onclick=()=>{if(subscriptionPage>1){subscriptionPage--;loadSubscriptions()}};subscriptionNext.onclick=()=>{if(!subscriptionNext.disabled){subscriptionPage++;loadSubscriptions()}};
function subscriptionForm(item,details){if(item.subscription_id){const p=document.createElement('p');p.textContent='Abonnement déjà enregistré.';details.append(p);return}if(!item.can_register_subscription)return;const form=document.createElement('form');form.className='editor';function field(name,label,type){const wrap=document.createElement('label'),input=document.createElement('input');wrap.textContent=label;input.name=name;input.type=type;input.required=true;wrap.append(input);form.append(wrap);return input}field('starts_on','Début contractuel','date');field('ends_on','Fin contractuelle (exclue)','date');field('reference','Référence du contrat signé','text').maxLength=500;const previous=field('predecessor_id','Identifiant de l’abonnement précédent (renouvellement facultatif)','text');previous.required=false;previous.maxLength=36;const save=document.createElement('button');save.textContent='Enregistrer l’abonnement';form.append(save);details.append(form);form.onsubmit=async e=>{e.preventDefault();const session=token;if(!token||!confirm('Confirmez-vous disposer d’un contrat signé correspondant à cette offre ?'))return;save.disabled=true;try{await api('crm/saas-subscriptions',{method:'POST',body:JSON.stringify({...Object.fromEntries(new FormData(form)),offer_id:item.id})});if(token===session){subscriptionPage=1;await Promise.all([loadSaasOffers(),loadSubscriptions()]);offerNotice.textContent='Abonnement enregistré dans le registre interne.'}}catch(error){if(token===session)offerNotice.textContent=error.message}finally{save.disabled=false}}}
const originalLogin=byId('login-form').onsubmit;byId('login-form').onsubmit=async e=>{await originalLogin(e);if(token){subscriptionPage=1;await loadSubscriptions()}};
const originalLogout=byId('logout').onclick;byId('logout').onclick=()=>{clearTimeout(subscriptionTimer);subscriptionEpoch++;subscriptionSearch.value='';subscriptionFilter.value='';subscriptionMetrics.replaceChildren();subscriptionRows.replaceChildren();subscriptionNotice.textContent='';subscriptionPageLabel.textContent='';originalLogout()};
function clearOfferWorkspace(){offerEpoch++;offerLookupEpoch++;offerForm.reset();offerOpportunity.replaceChildren(option('','Sélectionner'));offerRows.replaceChildren();offerNotice.textContent='';offerPageLabel.textContent='';offerSave.disabled=false}
offerFind.onclick=async()=>{const current=++offerLookupEpoch,session=token;try{const d=await api('crm?'+new URLSearchParams({q:offerSearch.value,page_size:25}));if(!token||token!==session||current!==offerLookupEpoch)return;offerOpportunity.replaceChildren(option('','Sélectionner'));for(const item of d.items)offerOpportunity.append(option(item.id,item.company+' — '+item.title));offerNotice.textContent=d.total>25?'Précisez la recherche (25 premiers résultats).':d.total+' opportunité(s).'}catch(e){if(token===session&&current===offerLookupEpoch)offerNotice.textContent=e.message}};
offerSearch.addEventListener('input',()=>{offerLookupEpoch++;offerOpportunity.replaceChildren(option('','Sélectionner'))});
const offerActionLabels={VALIDEE:'Valider en interne',TRANSMISE:'Enregistrer la transmission',ACCEPTEE:'Enregistrer l’acceptation client',REFUSEE:'Enregistrer le refus client',ANNULEE:'Annuler l’offre'};
function offerDecision(item,details){const history=document.createElement('ul');for(const event of item.history){const li=document.createElement('li');li.textContent=event.status+' · '+event.created_at+' · '+event.actor+' · '+event.evidence;history.append(li)}if(item.history.length)details.append(history);if(!item.actions.length)return;const form=document.createElement('form'),action=document.createElement('select'),evidence=document.createElement('textarea'),save=document.createElement('button');action.setAttribute('aria-label','Décision commerciale');for(const value of item.actions)action.append(option(value,offerActionLabels[value]));evidence.required=true;evidence.maxLength=1000;evidence.placeholder='Référence de la preuve ou motif';evidence.setAttribute('aria-label','Preuve de décision SaaS');save.textContent='Enregistrer la décision';form.append(action,evidence,save);details.append(form);form.onsubmit=async e=>{e.preventDefault();const session=token;if(!token||!confirm('Enregistrer cette décision commerciale ?'))return;save.disabled=true;try{await api('crm/saas-offers/'+encodeURIComponent(item.id)+'/decision',{method:'POST',body:JSON.stringify({version:item.version,action:action.value,evidence:evidence.value})});if(token===session){await loadSaasOffers();offerNotice.textContent='Décision SaaS enregistrée. Aucun envoi automatique.'}}catch(error){if(token===session)offerNotice.textContent=error.message}finally{save.disabled=false}}}
async function loadSaasOffers(){const current=++offerEpoch,session=token;try{const d=await api('crm/saas-offers?'+new URLSearchParams({page:offerPage}));if(!token||token!==session||current!==offerEpoch)return;offerRows.replaceChildren();for(const item of d.items){const details=document.createElement('details'),summary=document.createElement('summary');summary.textContent=item.title+' — '+item.company+' · '+item.estimate.product_name+' · '+item.status;details.append(summary);const description=document.createElement('p');description.textContent='Opportunité : '+item.opportunity_title+' · Validité : '+item.valid_until+' · '+item.estimate.first_year+' '+item.estimate.currency+' HT / première année estimée';details.append(description);const snapshot=document.createElement('p');snapshot.textContent='Période : '+item.inputs.cycle+' · Quantité : '+item.inputs.quantity+' · Prix unitaire : '+item.inputs.unit_price+' · Options : '+item.inputs.options+' · Installation : '+item.inputs.setup+' · Formation : '+item.inputs.training+' · MRR : '+item.estimate.mrr+' · ARR : '+item.estimate.arr+' '+item.estimate.currency;details.append(snapshot);offerDecision(item,details);subscriptionForm(item,details);offerRows.append(details)}offerPageLabel.textContent='Page '+offerPage+' · '+d.total+' offre(s)';offerPrev.disabled=offerPage===1;offerNext.disabled=offerPage*10>=d.total}catch(e){if(token===session&&current===offerEpoch)offerNotice.textContent=e.message}}
offerPrev.onclick=()=>{if(offerPage>1){offerPage--;loadSaasOffers()}};offerNext.onclick=()=>{if(!offerNext.disabled){offerPage++;loadSaasOffers()}};
offerForm.onsubmit=async e=>{e.preventDefault();if(!token||!saasForm.reportValidity())return;const session=token;const inputs=Object.fromEntries(new FormData(saasForm));inputs.quantity=Number(inputs.quantity);const data={opportunity_id:offerOpportunity.value,title:offerForm.elements.title.value,valid_until:offerForm.elements.valid_until.value,inputs};offerSave.disabled=true;try{await api('crm/saas-offers',{method:'POST',body:JSON.stringify(data)});if(token===session){offerForm.reset();offerOpportunity.replaceChildren(option('','Sélectionner'));offerLookupEpoch++;offerPage=1;await loadSaasOffers();offerNotice.textContent='Brouillon SaaS enregistré.'}}catch(e){if(token===session)offerNotice.textContent=e.message}finally{if(token===session)offerSave.disabled=false}};
function clearDiagnostic(){scResults.replaceChildren();scNotice.textContent=''}
scForm.addEventListener('reset',clearDiagnostic);
scForm.addEventListener('input',clearDiagnostic);
scForm.addEventListener('submit',e=>{
 e.preventDefault();clearDiagnostic();
 if(!token)return;
 const data=Object.fromEntries(new FormData(scForm));
 const keys=['shipments','on_time','otif','checked','accurate','cost','km'];
 const values=keys.map(k=>Number(data[k]));
 if(!scForm.checkValidity()||keys.some(k=>data[k].trim()==='')||values.some(v=>!Number.isSafeInteger(v)||v<0)){scNotice.textContent='Mesures invalides.';return}
 const [shipments,onTime,otif,checked,accurate,cost,km]=values;
 if(onTime>shipments||otif>onTime||accurate>checked){scNotice.textContent='Incohérence : vérifiez les volumes et les sous-totaux.';return}
 const format=n=>n.toLocaleString('fr-FR',{maximumFractionDigits:2});
 const rate=(n,d)=>d?format(100*n/d)+' %':'Non calculable';
 const unit=(n,d)=>d?format(n/d)+' '+data.currency:'Non calculable';
 const metrics=[['Livraisons à l’heure',rate(onTime,shipments)],['OTIF (à l’heure et complètes)',rate(otif,shipments)],['Exactitude du stock',rate(accurate,checked)],['Coût par livraison',unit(cost,shipments)],['Coût par km',unit(cost,km)]];
 for(const [label,value] of metrics){const box=document.createElement('div');box.className='count';const strong=document.createElement('strong');strong.textContent=value;box.append(strong,document.createTextNode(label));scResults.append(box)}
 scNotice.textContent='Diagnostic calculé pour '+data.period+' — '+data.currency+'. Les valeurs non calculables correspondent aux dénominateurs nuls.';
});
